"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command "# Check for files in SHA256SUMS that don't exist on disk (missing files)
"'$base = "E:'"\\codex-LOOP\\codex-loop-s-f2\"
"'$lines = Get-Content "$base'"\\SHA256SUMS\"
"'$missing = @()
foreach ($line in $lines) {
  if ($line.Trim() -eq "") { continue }
  $parts = $line -split '"'\\s+', 2
  if ("'$parts.Count -lt 2) { continue }
  $relPath = $parts[1]
  $full = Join-Path $base ($relPath.Replace("/", "'"\\\"))
  if (-not (Test-Path "'$full)) {
    $missing += $relPath
  }
}
Write-Output "=== Files in SHA256SUMS but MISSING from disk ==="
if ($missing.Count -eq 0) {
  Write-Output "  (none)"
} else {
  $missing | ForEach-Object { Write-Output "  MISSING: $_" }
}'

