"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Cross-compare recorded hashes vs actual for all tracked files
$base = "E:'"\\codex-LOOP\\codex-loop-s-f2\"
"'$lines = Get-Content "$base'"\\SHA256SUMS\"
"'$mismatches = @()
$matches = @()
foreach ($line in $lines) {
  if ($line.Trim() -eq "") { continue }
  $parts = $line -split '"'\\s+', 2
  if ("'$parts.Count -lt 2) { continue }
  $recorded = $parts[0].ToLower()
  $relPath = $parts[1]
  $full = Join-Path $base ($relPath.Replace("/", "'"\\\"))
  if (Test-Path "'$full) {
    $actual = (Get-FileHash $full -Algorithm SHA256).Hash.ToLower()
    if ($actual -ne $recorded) {
      $mismatches += [PSCustomObject]@{ File=$relPath; Recorded=$recorded; Actual=$actual }
    } else {
      $matches += $relPath
    }
  }
}
Write-Output "=== HASH MISMATCHES (DRIFT DETECTED) ==="
if ($mismatches.Count -eq 0) {
  Write-Output "  (none - all tracked files match)"
} else {
  foreach ($m in $mismatches) {
    Write-Output "  MISMATCH: $($m.File)"
    Write-Output "    recorded: $($m.Recorded)"
    Write-Output "    actual:   $($m.Actual)"
  }
}
Write-Output ""
Write-Output "Total tracked files verified OK: $($matches.Count)"
Write-Output "Total mismatches: $($mismatches.Count)"'

